import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d,i as D,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"STRIDE","description":"","frontmatter":{"title":"STRIDE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stride.md","filePath":"cs/stride.md","lastUpdated":1789023840000}'),c={name:"cs/stride.md"};function h(p,a,_,A,m,T){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="stride" tabindex="-1">STRIDE <a class="header-anchor" href="#stride" aria-label="Permalink to &quot;STRIDE&quot;">​</a></h1><div class="epigraph"><p>伪造、篡改、否认、信息泄露、拒绝服务、越权：六类检查清单，把威胁模型从一张空图变成可枚举的问句。</p><footer>—— 据 Howard and Lipner；Shostack, Threat Modeling；Anderson 对把威胁写下来的强调</footer></div><p><a href="/cs/threat-model">上一课</a>要求先写敌手、资产与信任边界。本课不重画 Kerckhoffs。缺口是检查时容易漏轴：<a href="/cs/cia-triad">CIA</a> 是三根，工程审查常用 STRIDE 六类把「谁能干什么」问全。它是清单，不是攻击教程。后课 Dolev–Yao 再把网络敌手收成代数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>威胁模型课留下「映射到机制」。评审一张数据流图时，每个过程、每个数据流、每个存储都要问：身份能否被假冒，数据能否被改，事件能否被抵赖，秘密能否流出，服务能否被停，授权能否被绕过。缺口是<strong>把这些问题命名成 STRIDE</strong>，避免只盯着加密。</p><p><span class="marginnote">STRIDE 来自微软一线教材，不是密码学定理。否认（R）常要日志与签名，和 CIA 的 I 相关但不相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对图上每个元素过六问，记下「不防谁」。然后才选后课机制：对称加密对泄露，MAC 对篡改，认证对伪造，隔离对越权，容量设计对 DoS。本课不把某一次审查表格当标准正文。</p>',8)),(e(),n(E,null,{default:r(()=>[D(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DFD%5B%22%E6%95%B0%E6%8D%AE%E6%B5%81%E5%9B%BE%22%5D%20--%3E%20S%5B%22%E4%BC%AA%E9%80%A0%22%5D%0A%20%20DFD%20--%3E%20T%5B%22%E7%AF%A1%E6%94%B9%22%5D%0A%20%20DFD%20--%3E%20R%5B%22%E5%90%A6%E8%AE%A4%22%5D%0A%20%20DFD%20--%3E%20I%5B%22%E6%B3%84%E9%9C%B2%22%5D%0A%20%20DFD%20--%3E%20D%5B%22%E6%8B%92%E7%BB%9D%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20DFD%20--%3E%20E%5B%22%E8%B6%8A%E6%9D%83%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>清单迫使每个信任边界都有对应控制，而不是全局一句「有 TLS」。它与后课访问控制、握手、沙箱是多对多：一种机制可挡多类，一类威胁要多层。本栏不提供利用步骤，只要求设计时能指出控制落点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 STRIDE 当成完备分类，不引入攻击树的全部记号。能改写、能注入的网络敌手下一课用 Dolev–Yao 形式化。</p><p>后课默认：审查用六类问句。协议层敌手能力下一课钉死。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>STRIDE 是威胁模型上的检查清单，不是新的 CIA。</li><li>每问应对到后课某一机制。</li><li>网络代数敌手下一课 Dolev–Yao。</li><li>出处：Howard and Lipner；Shostack；Anderson, <em>Security Engineering</em>。</li></ul>',7))])}const u=i(c,[["render",h]]);export{f as __pageData,u as default};
